def solve(grid, start, goal):
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])
    directions = [(0,1), (1, 0), (0,-1), (-1, 0)]
    stack = [start]
    visited = set(start)

    while stack:
        current = stack.pop()
        for dr, dc in directions:
            neighbor = (current[0] + dr, current[1] + dc)
            if (0 <= neighbor[0] < rows and 0 <= neighbor[1] < cols and
                neighbor not in visited and grid[neighbor[0]][neighbor[1]] == '.'):
                if neighbor == goal:
                    path = [neighbor]
                    while current != start:
                        path.append(current)
                        for drc in directions:
                            prev = (current[0] - drc[0], current[1] - drc[1])
                            if prev in visited and grid[prev[0]][prev[1]] == '.':
                                current = prev
                                break
                    path.append(start)
                    return path[::-1]
                visited.add(neighbor)
                stack.append(neighbor)

    return []

